function(container, apiUrl, tables) {
  // ローカルストレージキー
  const LOCAL_STORAGE_KEY = 'work_records_local';
  const SETTINGS_KEY = 'autosave_settings';

  // 設定の初期化
  let settings = {
    interval: 60,
    localSave: 'enabled'
  };

  try {
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedSettings) {
      settings = { ...settings, ...JSON.parse(savedSettings) };
    }
  } catch (e) {
    console.error('設定読み込みエラー:', e);
  }

  // UI要素の取得
  const statusIndicator = container.querySelector('#status-indicator');
  const statusText = container.querySelector('#status-text');
  const networkIndicator = container.querySelector('#network-indicator');
  const networkText = container.querySelector('#network-text');
  const pendingCount = container.querySelector('#pending-count');
  const lastSaveTime = container.querySelector('#last-save-time');
  const localDataTbody = container.querySelector('#local-data-tbody');
  const errorNotifications = container.querySelector('#error-notifications');
  const errorList = container.querySelector('#error-list');

  // ローカルデータ再描画関数
  function renderLocalData() {
    try {
      const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
      const rows = Object.keys(localData).map(key => {
        const data = localData[key];
        const count = Array.isArray(data) ? data.length : Object.keys(data).length;
        const lastUpdate = data.lastUpdate || '未更新';
        const status = data.synced ? '同期済み' : '同期待ち';

        return `
          <tr data-key="${key}">
            <td>${key}</td>
            <td>${count}</td>
            <td style="font-size: 11px;">${lastUpdate}</td>
            <td>
              <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${data.synced ? '#22c55e' : '#f59e0b'}; color: white;">
                ${status}
              </span>
            </td>
            <td>
              <button class="action-btn secondary sync-btn" data-key="${key}" style="font-size: 11px; padding: 4px 8px;">同期</button>
            </td>
          </tr>
        `;
      });

      localDataTbody.innerHTML = rows.join('');

      // 同期待ち件数の更新
      const pendingItems = Object.values(localData).filter(data => !data.synced).length;
      pendingCount.textContent = pendingItems;

    } catch (e) {
      console.error('ローカルデータ描画エラー:', e);
      localDataTbody.innerHTML = '<tr><td colspan="5">データ読み込みエラー</td></tr>';
    }
  }

  // ネットワーク状態チェック
  function checkNetworkStatus() {
    const isOnline = navigator.onLine;
    networkIndicator.style.background = isOnline ? '#22c55e' : '#ef4444';
    networkText.textContent = isOnline ? 'オンライン' : 'オフライン';

    if (!isOnline) {
      statusIndicator.style.background = '#f59e0b';
      statusText.textContent = 'オフライン動作中';
    }
  }

  // エラー表示
  function showError(message) {
    errorList.innerHTML = `<div style="margin-bottom: 4px;">${new Date().toLocaleString()}: ${message}</div>` + errorList.innerHTML;
    errorNotifications.style.display = 'block';
  }

  // 自動保存処理
  let autoSaveInterval;
  function startAutoSave() {
    if (autoSaveInterval) clearInterval(autoSaveInterval);

    autoSaveInterval = setInterval(async () => {
      try {
        // 作業記録の自動保存をシミュレート
        const now = new Date().toLocaleString();
        lastSaveTime.textContent = now;

        // ローカルストレージに保存
        if (settings.localSave === 'enabled') {
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
          localData['作業記録'] = {
            data: tables[1]?.records || [],
            lastUpdate: now,
            synced: navigator.onLine
          };
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          renderLocalData();
        }

        statusIndicator.style.background = '#22c55e';
        statusText.textContent = '正常動作中';

      } catch (error) {
        console.error('自動保存エラー:', error);
        statusIndicator.style.background = '#ef4444';
        statusText.textContent = '保存エラー';
        showError('自動保存に失敗しました');
      }
    }, settings.interval * 1000);
  }

  // 設定保存
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const interval = parseInt(container.querySelector('#save-interval').value);
    const localSave = container.querySelector('#local-save').value;

    settings = { interval, localSave };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));

    // 自動保存間隔の更新
    startAutoSave();

    alert('設定を保存しました');
  });

  // 手動同期
  container.querySelector('#btn-sync').addEventListener('click', async () => {
    try {
      const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
      let syncCount = 0;

      for (const [key, data] of Object.entries(localData)) {
        if (!data.synced && Array.isArray(data.data)) {
          // 作業記録の同期
          for (const record of data.data) {
            if (!record.synced) {
              const saved = await window.aivicApi.save(1, record);
              if (saved) {
                record.synced = true;
                syncCount++;
              }
            }
          }
          data.synced = true;
        }
      }

      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
      renderLocalData();

      alert(`${syncCount}件のデータを同期しました`);

    } catch (error) {
      console.error('同期エラー:', error);
      showError('データ同期に失敗しました');
    }
  });

  // ローカルデータ削除
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (confirm('ローカル保存データを削除しますか？\n※同期されていないデータは失われます。')) {
      localStorage.removeItem(LOCAL_STORAGE_KEY);
      renderLocalData();
      alert('ローカルデータを削除しました');
    }
  });

  // データ復旧
  container.querySelector('#btn-recovery').addEventListener('click', async () => {
    const recoveryDate = container.querySelector('#recovery-date').value;
    if (!recoveryDate) {
      alert('復旧対象日を選択してください');
      return;
    }

    if (confirm(`${recoveryDate}のデータを復旧しますか？`)) {
      try {
        // 指定日のデータを取得（実際の実装では日付フィルタリング）
        const records = await window.aivicApi.list(1);
        const targetRecords = records?.filter(r => 
          r.作業日 && r.作業日.startsWith(recoveryDate)
        ) || [];

        // ローカルストレージに復旧データを保存
        const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
        localData[`復旧データ_${recoveryDate}`] = {
          data: targetRecords,
          lastUpdate: new Date().toLocaleString(),
          synced: false
        };
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));

        renderLocalData();
        alert(`${targetRecords.length}件のデータを復旧しました`);

      } catch (error) {
        console.error('復旧エラー:', error);
        showError('データ復旧に失敗しました');
      }
    }
  });

  // バックアップ作成
  container.querySelector('#btn-backup').addEventListener('click', async () => {
    try {
      const records = await window.aivicApi.list(1);
      if (!records) {
        showError('バックアップデータの取得に失敗しました');
        return;
      }

      const backup = {
        timestamp: new Date().toISOString(),
        records: records
      };

      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `work_records_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      URL.revokeObjectURL(url);

      alert('バックアップファイルをダウンロードしました');

    } catch (error) {
      console.error('バックアップエラー:', error);
      showError('バックアップ作成に失敗しました');
    }
  });

  // イベントデリゲーション（個別同期）
  container.addEventListener('click', async (e) => {
    const syncBtn = e.target.closest('.sync-btn');
    if (syncBtn) {
      const key = syncBtn.dataset.key;
      try {
        const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '{}');
        if (localData[key] && !localData[key].synced) {
          // 同期処理（簡略化）
          localData[key].synced = true;
          localData[key].lastUpdate = new Date().toLocaleString();
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          renderLocalData();
          alert(`${key}を同期しました`);
        }
      } catch (error) {
        console.error('同期エラー:', error);
        showError(`${key}の同期に失敗しました`);
      }
    }
  });

  // ネットワーク状態監視
  window.addEventListener('online', checkNetworkStatus);
  window.addEventListener('offline', checkNetworkStatus);

  // 設定値の復元
  container.querySelector('#save-interval').value = settings.interval;
  container.querySelector('#local-save').value = settings.localSave;

  // 初期化
  checkNetworkStatus();
  renderLocalData();
  startAutoSave();

  // 復旧対象日のデフォルト値設定
  container.querySelector('#recovery-date').value = new Date().toISOString().split('T')[0];
}
